const pptxgen = require("pptxgenjs");

// ============================================================
// COLOR PALETTE: Ocean Gradient (data-driven, professional)
// ============================================================
const COLORS = {
  primary: "065A82",    // deep blue
  secondary: "1C7293",  // teal
  accent: "21295C",     // midnight
  light: "F8FAFC",      // off-white background
  white: "FFFFFF",
  darkText: "1E293B",
  mutedText: "64748B",
  chartColors: ["065A82", "1C7293", "21295C", "0D9488", "14B8A6", "5EEAD4", "F59E0B", "EF4444"]
};

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.author = "JetBrains State of Developer Ecosystem 2024";
pres.title = "State of Developer Ecosystem 2024: Language Trends, Satisfaction, and Strategic Shifts";
pres.subject = "Programming language landscape analysis for engineering leaders";

// ============================================================
// SLIDE 1: TITLE
// ============================================================
{
  let slide = pres.addSlide();
  slide.background = { color: COLORS.accent };

  // Decorative top accent bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.12,
    fill: { color: COLORS.primary }
  });

  // Small stat callout boxes at top
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.6, y: 0.5, w: 2.6, h: 0.9,
    fill: { color: COLORS.primary, transparency: 25 }
  });
  slide.addText("23,262", {
    x: 0.6, y: 0.55, w: 2.6, h: 0.45,
    fontSize: 28, bold: true, color: COLORS.white,
    align: "center", valign: "middle", fontFace: "Calibri"
  });
  slide.addText("Developers Surveyed", {
    x: 0.6, y: 0.95, w: 2.6, h: 0.35,
    fontSize: 11, color: COLORS.white,
    align: "center", valign: "middle", fontFace: "Calibri"
  });

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 3.7, y: 0.5, w: 2.6, h: 0.9,
    fill: { color: COLORS.primary, transparency: 25 }
  });
  slide.addText("8 Years", {
    x: 3.7, y: 0.55, w: 2.6, h: 0.45,
    fontSize: 28, bold: true, color: COLORS.white,
    align: "center", valign: "middle", fontFace: "Calibri"
  });
  slide.addText("of Trend Data (2017-2024)", {
    x: 3.7, y: 0.95, w: 2.6, h: 0.35,
    fontSize: 11, color: COLORS.white,
    align: "center", valign: "middle", fontFace: "Calibri"
  });

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.8, y: 0.5, w: 2.6, h: 0.9,
    fill: { color: COLORS.primary, transparency: 25 }
  });
  slide.addText("20+", {
    x: 6.8, y: 0.55, w: 2.6, h: 0.45,
    fontSize: 28, bold: true, color: COLORS.white,
    align: "center", valign: "middle", fontFace: "Calibri"
  });
  slide.addText("Languages Tracked", {
    x: 6.8, y: 0.95, w: 2.6, h: 0.35,
    fontSize: 11, color: COLORS.white,
    align: "center", valign: "middle", fontFace: "Calibri"
  });

  // Main title
  slide.addText("State of Developer Ecosystem 2024", {
    x: 0.6, y: 1.9, w: 8.8, h: 0.7,
    fontSize: 40, bold: true, color: COLORS.white,
    fontFace: "Calibri", align: "left", valign: "middle"
  });

  // Subtitle
  slide.addText("Language Trends, Satisfaction, and Strategic Shifts", {
    x: 0.6, y: 2.55, w: 8.8, h: 0.45,
    fontSize: 22, color: "94A3B8",
    fontFace: "Calibri", align: "left", valign: "middle"
  });

  // Divider line
  slide.addShape(pres.shapes.LINE, {
    x: 0.6, y: 3.15, w: 3.5, h: 0,
    line: { color: COLORS.primary, width: 2 }
  });

  // Context paragraph
  slide.addText("JetBrains' annual survey captures the most comprehensive snapshot of the global developer community — covering programming languages, tooling preferences, AI attitudes, and career trends.", {
    x: 0.6, y: 3.4, w: 6.5, h: 1.2,
    fontSize: 14, color: "CBD5E1",
    fontFace: "Calibri", align: "left", valign: "top"
  });

  // Source footer
  slide.addText("Source: JetBrains State of Developer Ecosystem Report 2024", {
    x: 0.6, y: 5.15, w: 8.8, h: 0.25,
    fontSize: 10, color: "94A3B8", italic: true,
    fontFace: "Calibri", align: "left", valign: "middle"
  });
}

// ============================================================
// SLIDE 2: LANGUAGE TRENDS (Line Chart)
// ============================================================
{
  let slide = pres.addSlide();
  slide.background = { color: COLORS.light };

  // Title
  slide.addText("Python Closes the Gap: 8 Years of Language Usage Shifts", {
    x: 0.5, y: 0.35, w: 9, h: 0.55,
    fontSize: 28, bold: true, color: COLORS.darkText,
    fontFace: "Calibri", align: "left", valign: "middle"
  });

  // Subtitle text
  slide.addText("Usage share of top programming languages, 2017-2024 (% of developers)", {
    x: 0.5, y: 0.85, w: 9, h: 0.3,
    fontSize: 12, color: COLORS.mutedText, italic: true,
    fontFace: "Calibri", align: "left", valign: "middle"
  });

  // Line chart data: top 8 languages
  const chartData = [
    { name: "JavaScript", labels: ["2017", "2020", "2022", "2024"], values: [65, 70, 65, 61] },
    { name: "Python",     labels: ["2017", "2020", "2022", "2024"], values: [32, 55, 53, 57] },
    { name: "HTML/CSS",   labels: ["2017", "2020", "2022", "2024"], values: [60, 61, 54, 51] },
    { name: "SQL",        labels: ["2017", "2020", "2022", "2024"], values: [42, 56, 49, 48] },
    { name: "Java",       labels: ["2017", "2020", "2022", "2024"], values: [47, 54, 48, 46] },
    { name: "TypeScript", labels: ["2017", "2020", "2022", "2024"], values: [12, 28, 34, 37] },
    { name: "Go",         labels: ["2017", "2020", "2022", "2024"], values: [8,  19, 19, 18] },
    { name: "Rust",       labels: ["2017", "2020", "2022", "2024"], values: [0,  7,  9,  11] }
  ];

  slide.addChart(pres.charts.LINE, chartData, {
    x: 0.5, y: 1.25, w: 9, h: 3.6,
    lineSize: 3,
    lineSmooth: true,
    chartColors: ["065A82", "14B8A6", "64748B", "F59E0B", "EF4444", "21295C", "8B5CF6", "EC4899"],
    chartArea: { fill: { color: COLORS.white }, roundedCorners: true },
    catAxisLabelColor: COLORS.mutedText,
    valAxisLabelColor: COLORS.mutedText,
    valGridLine: { color: "E2E8F0", size: 0.5 },
    catGridLine: { style: "none" },
    showLegend: true,
    legendPos: "b",
    legendFontSize: 10,
    legendColor: COLORS.darkText,
    showValue: false,
    dataLabelPosition: "outEnd",
    dataLabelColor: COLORS.darkText,
    dataLabelFontSize: 9,
    valAxisMaxVal: 80,
    valAxisMinVal: 0,
    valAxisTitle: "Usage %",
    valAxisTitleFontSize: 10,
    valAxisTitleColor: COLORS.mutedText
  });

  // Key insight callout
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 5.05, w: 9, h: 0.45,
    fill: { color: COLORS.accent }
  });
  slide.addText("Key Insight: Python rose from 32% to 57% while JavaScript declined from a 70% peak to 61%. TypeScript tripled from 12% to 37%.", {
    x: 0.5, y: 5.05, w: 9, h: 0.45,
    fontSize: 12, color: COLORS.white, bold: true,
    fontFace: "Calibri", align: "center", valign: "middle", margin: 0.1
  });
}

// ============================================================
// SLIDE 3: PRIMARY LANGUAGE (Horizontal Bar + Adoption Intent)
// ============================================================
{
  let slide = pres.addSlide();
  slide.background = { color: COLORS.light };

  slide.addText("Python Is Now the #1 Primary Language at 35%", {
    x: 0.5, y: 0.35, w: 9, h: 0.55,
    fontSize: 28, bold: true, color: COLORS.darkText,
    fontFace: "Calibri", align: "left", valign: "middle"
  });

  slide.addText("Primary language share vs. adoption intent (% of developers)", {
    x: 0.5, y: 0.85, w: 9, h: 0.3,
    fontSize: 12, color: COLORS.mutedText, italic: true,
    fontFace: "Calibri", align: "left", valign: "middle"
  });

  // Horizontal bar chart: primary language
  const primaryData = [
    { name: "Primary Language", labels: ["Python", "Java", "JavaScript", "TypeScript", "SQL"], values: [35, 30, 28, 19, 17] }
  ];

  slide.addChart(pres.charts.BAR, primaryData, {
    x: 0.5, y: 1.25, w: 5.5, h: 3.6,
    barDir: "bar",
    barGrouping: "clustered",
    chartColors: [COLORS.primary],
    chartArea: { fill: { color: COLORS.white }, roundedCorners: true },
    catAxisLabelColor: COLORS.darkText,
    valAxisLabelColor: COLORS.mutedText,
    valGridLine: { color: "E2E8F0", size: 0.5 },
    catGridLine: { style: "none" },
    showLegend: false,
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: COLORS.darkText,
    dataLabelFontSize: 11,
    dataLabelBold: true,
    valAxisMaxVal: 40,
    valAxisMinVal: 0,
    catAxisTitle: "",
    valAxisTitle: "",
    title: "Primary Language",
    titleFontSize: 12,
    titleColor: COLORS.mutedText,
    titleBold: false
  });

  // Adoption intent small bar chart
  const adoptData = [
    { name: "Adoption Intent", labels: ["Python", "TypeScript", "Java", "SQL", "Go"], values: [6, 5, 4, 4, 3] }
  ];

  slide.addChart(pres.charts.BAR, adoptData, {
    x: 6.3, y: 1.25, w: 3.2, h: 3.6,
    barDir: "bar",
    barGrouping: "clustered",
    chartColors: [COLORS.secondary],
    chartArea: { fill: { color: COLORS.white }, roundedCorners: true },
    catAxisLabelColor: COLORS.darkText,
    valAxisLabelColor: COLORS.mutedText,
    valGridLine: { color: "E2E8F0", size: 0.5 },
    catGridLine: { style: "none" },
    showLegend: false,
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: COLORS.darkText,
    dataLabelFontSize: 11,
    dataLabelBold: true,
    valAxisMaxVal: 10,
    valAxisMinVal: 0,
    title: "Adoption Intent",
    titleFontSize: 12,
    titleColor: COLORS.mutedText,
    titleBold: false
  });

  // Insight box
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 5.05, w: 9, h: 0.45,
    fill: { color: COLORS.accent }
  });
  slide.addText("Insight: Adoption intent stays below 6% across all languages — developers rarely switch primary stacks.", {
    x: 0.5, y: 5.05, w: 9, h: 0.45,
    fontSize: 12, color: COLORS.white, bold: true,
    fontFace: "Calibri", align: "center", valign: "middle", margin: 0.1
  });
}

// ============================================================
// SLIDE 4: DEVELOPER SATISFACTION (Horizontal Bar Chart)
// ============================================================
{
  let slide = pres.addSlide();
  slide.background = { color: COLORS.light };

  slide.addText("TypeScript and Rust Top Developer Satisfaction, Nearly Tied at 199 vs 198", {
    x: 0.5, y: 0.35, w: 9, h: 0.55,
    fontSize: 26, bold: true, color: COLORS.darkText,
    fontFace: "Calibri", align: "left", valign: "middle"
  });

  slide.addText("Satisfaction scores reflect developer enthusiasm for type safety, modern tooling, and expressive type systems", {
    x: 0.5, y: 0.85, w: 9, h: 0.3,
    fontSize: 12, color: COLORS.mutedText, italic: true,
    fontFace: "Calibri", align: "left", valign: "middle"
  });

  const satData = [
    { name: "Satisfaction Score", labels: ["TypeScript", "Rust", "Python", "Go", "Lua", "C++", "Kotlin", "Shell", "Dart", "C"], values: [199, 198, 151, 129, 118, 113, 113, 100, 93, 86] }
  ];

  slide.addChart(pres.charts.BAR, satData, {
    x: 0.5, y: 1.25, w: 9, h: 3.6,
    barDir: "bar",
    barGrouping: "clustered",
    chartColors: [COLORS.primary],
    chartArea: { fill: { color: COLORS.white }, roundedCorners: true },
    catAxisLabelColor: COLORS.darkText,
    valAxisLabelColor: COLORS.mutedText,
    valGridLine: { color: "E2E8F0", size: 0.5 },
    catGridLine: { style: "none" },
    showLegend: false,
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: COLORS.darkText,
    dataLabelFontSize: 11,
    dataLabelBold: true,
    valAxisMaxVal: 220,
    valAxisMinVal: 0
  });

  // Insight box
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 5.05, w: 9, h: 0.45,
    fill: { color: COLORS.accent }
  });
  slide.addText("Top 2 are type-safe languages with modern tooling. Python's #3 position (151) is driven by its AI/ML dominance.", {
    x: 0.5, y: 5.05, w: 9, h: 0.45,
    fontSize: 12, color: COLORS.white, bold: true,
    fontFace: "Calibri", align: "center", valign: "middle", margin: 0.1
  });
}

// ============================================================
// SLIDE 5: DOMAIN SPECIALIZATION (Structured Table)
// ============================================================
{
  let slide = pres.addSlide();
  slide.background = { color: COLORS.light };

  slide.addText("Each Language Owns a Domain: AI Belongs to Python, UI to TypeScript", {
    x: 0.5, y: 0.35, w: 9, h: 0.55,
    fontSize: 26, bold: true, color: COLORS.darkText,
    fontFace: "Calibri", align: "left", valign: "middle"
  });

  slide.addText("Language choice is driven by application domain, not general preference", {
    x: 0.5, y: 0.85, w: 9, h: 0.3,
    fontSize: 12, color: COLORS.mutedText, italic: true,
    fontFace: "Calibri", align: "left", valign: "middle"
  });

  // Table: domain specialization
  const tableRows = [
    [
      { text: "Application Domain", options: { fill: { color: COLORS.primary }, color: COLORS.white, bold: true, align: "left" } },
      { text: "Leading Language", options: { fill: { color: COLORS.primary }, color: COLORS.white, bold: true, align: "center" } },
      { text: "Share", options: { fill: { color: COLORS.primary }, color: COLORS.white, bold: true, align: "center" } }
    ],
    [
      { text: "AI / Machine Learning", options: { fill: { color: COLORS.white }, color: COLORS.darkText, align: "left" } },
      { text: "Python", options: { fill: { color: "E0F2FE" }, color: COLORS.primary, bold: true, align: "center" } },
      { text: "31%", options: { fill: { color: COLORS.white }, color: COLORS.darkText, align: "center" } }
    ],
    [
      { text: "Data Science / Analytics", options: { fill: { color: "F8FAFC" }, color: COLORS.darkText, align: "left" } },
      { text: "Python", options: { fill: { color: "E0F2FE" }, color: COLORS.primary, bold: true, align: "center" } },
      { text: "28%", options: { fill: { color: "F8FAFC" }, color: COLORS.darkText, align: "center" } }
    ],
    [
      { text: "User Interface Development", options: { fill: { color: COLORS.white }, color: COLORS.darkText, align: "left" } },
      { text: "TypeScript", options: { fill: { color: "FEF3C7" }, color: "B45309", bold: true, align: "center" } },
      { text: "62%", options: { fill: { color: COLORS.white }, color: COLORS.darkText, align: "center" } }
