// SLIDE 6: STRATEGIC TAKEAWAYS
// ============================================================
{
  let slide = pres.addSlide();
  slide.background = { color: COLORS.accent };

  // Top accent
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.12,
    fill: { color: COLORS.primary }
  });

  slide.addText("What This Means for Your Technology Strategy in 2025", {
    x: 0.6, y: 0.4, w: 8.8, h: 0.6,
    fontSize: 30, bold: true, color: COLORS.white,
    fontFace: "Calibri", align: "left", valign: "middle"
