  // 5 takeaway cards
  const cards = [
    {
      num: "01",
      title: "Invest in Python for AI/ML Teams",
      body: "Python is the undisputed leader in AI (31%), data science (28%), and data processing. Build your AI talent pipeline around it."
    },
    {
      num: "02",
      title: "TypeScript Is the Future of Frontend",
      body: "Tripled usage to 37% and tops satisfaction at 199. It now dominates UI development (62%). Standardize on it for web and full-stack."
    },
    {
      num: "03",
      title: "Rust and Go Are Infrastructure Growth Plays",
      body: "Go stabilized at ~18%; Rust climbed to 11%. Both target cloud-native, microservices, and systems where performance is non-negotiable."
