    {
      num: "04",
      title: "PHP and Ruby Hiring Pools Are Shrinking",
      body: "PHP dropped from 30% to 17%; Ruby fell from 10% to 4%. Plan succession or migration if these are still in your stack."
    },
    {
      num: "05",
      title: "Satisfaction Correlates with Retention",
      body: "TypeScript and Rust lead satisfaction thanks to type safety and modern tooling. Factor developer experience into your retention strategy."
    }
  ];

  const startY = 1.2;
  const cardH = 0.72;
  const gap = 0.12;

  cards.forEach((card, i) => {
    const y = startY + i * (cardH + gap);

    // Card background
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.6, y: y, w: 8.8, h: cardH,
      fill: { color: COLORS.primary, transparency: 30 }
    });

    // Number circle
    slide.addShape(pres.shapes.OVAL, {
      x: 0.75, y: y + 0.16, w: 0.4, h: 0.4,
      fill: { color: COLORS.primary }
    });
    slide.addText(card.num, {
      x: 0.75, y: y + 0.16, w: 0.4, h: 0.4,
      fontSize: 14, bold: true, color: COLORS.white,
      align: "center", valign: "middle", fontFace: "Calibri"
    });

    // Title
    slide.addText(card.title, {
      x: 1.35, y: y + 0.08, w: 7.9, h: 0.3,
      fontSize: 14, bold: true, color: COLORS.white,
      fontFace: "Calibri", align: "left", valign: "middle"
    });

    // Body
    slide.addText(card.body, {
      x: 1.35, y: y + 0.36, w: 7.9, h: 0.32,
      fontSize: 11, color: "CBD5E1",
      fontFace: "Calibri", align: "left", valign: "top"
    });
  });

  // Footer
  slide.addText("Source: JetBrains State of Developer Ecosystem Report 2024 (n=23,262)", {
    x: 0.6, y: 5.15, w: 8.8, h: 0.25,
    fontSize: 10, color: "94A3B8", italic: true,
    fontFace: "Calibri", align: "left", valign: "middle"
  });
}

